// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"airdrop":{"slug":"airdrop","cat":"basics","en":"Airdrop","contentLocale":"tr","term":"Airdrop","aka":["airdrop","token dağıtımı","ücretsiz token dağıtımı"],"short":"Airdrop, bir projenin token'larını belirli koşulları sağlayan cüzdanlara veya kullanıcılara ücretsiz olarak dağıtmasıdır; genellikle erken kullanıcıları ödüllendirmek ve token'ı geniş bir kitleye yaymak amacıyla yapılır.","body":["Bazı airdrop'lar, belirli bir tarihte (snapshot) bir protokolü kullanmış cüzdanlara yapılır; Uniswap ve Arbitrum gibi projeler bu yöntemi kullandı. Bazıları ise borsaların kampanyaları üzerinden, belirli bir token'ı tutan kullanıcılara dağıtılır. Kriterler önceden açıklanmayabilir.","Airdrop token'ları çoğu zaman claim edilmesi, yani resmi sitede bir işlemle talep edilmesi gerekir. Bu adım dolandırıcıların en sevdiği alandır: sahte claim siteleri, cüzdanınızı bağlayıp bir izin imzalatarak varlıklarınızı boşaltmaya çalışır.","Cüzdanınıza istemediğiniz token'lar da gelebilir. Bunlarla etkileşime girmemek, satmaya çalışmamak ve içindeki linklere tıklamamak en güvenli yaklaşımdır. Airdrop'ların vergi açısından nasıl değerlendirildiği ülkeye göre değişir."],"example":["Bir protokolün, snapshot tarihine kadar en az 5 işlem yapmış cüzdanlara 800 token dağıttığını varsayalım. Token listelendiğinde 0,60 ",["USDT","usdt"],"'den işlem görürse payınızın değeri 800 x 0,60 = 480 USDT olur. Claim işlemi için 3 USDT gas ödersiniz. Ancak birçok kullanıcı aynı anda satarsa fiyat ilk günlerde örneğin 0,40 USDT'ye düşebilir ve aynı 800 token 320 USDT eder. Ayrıca token'ların bir kısmı kilitli dağıtılmışsa yalnızca açık kısmını hemen kullanabilirsiniz."],"mistakes":["Sosyal medyada paylaşılan claim linklerini resmi kaynaklardan doğrulamadan cüzdan bağlamak.","Airdrop için kurtarma ifadesi veya özel anahtar isteyen herhangi bir siteye bilgi girmek.","Cüzdana kendiliğinden gelen bilinmeyen token'ları satmak için tanımadığınız sitelere izin vermek."],"faq":[{"q":"Airdrop ücretsiz mi?","a":"Token'lar ücretsiz dağıtılır, ancak claim işlemi için gas ödemeniz gerekebilir. Sizden ödeme veya ön yatırım isteyen bir airdrop büyük olasılıkla dolandırıcılıktır."},{"q":"Airdrop'a nasıl uygun olurum?","a":"Kriterler projeden projeye değişir; genellikle protokolü gerçekten kullanmak, belirli bir token'ı tutmak veya borsa kampanyalarına katılmak gerekir. Kesin kuralları yalnızca projenin resmi kanallarından öğrenin."}],"title":"Airdrop nedir? Kripto airdrop nasıl çalışır?","description":"Kripto airdrop'un ne olduğunu, token'ların nasıl claim edildiğini ve sahte airdrop sitelerinden nasıl korunacağınızı öğrenin.","related":[["phishing","Oltalama (phishing)","Oltalama (phishing), dolandırıcıların sahte web siteleri, e-postalar, mesajlar veya reklamlar kullanarak sizden şifre, 2FA kodu, kurtarma ifadesi almaya ya da zararlı bir işlemi imzalatmaya çalıştığı saldırıdır."],["token-approval","Token onayı (token approval / allowance)","Token onayı, cüzdanınızdaki belirli bir token'ı sizin adınıza harcayabilmesi için bir akıllı sözleşmeye verdiğiniz izindir ve sınırsız verilen onaylar istismar edilirse cüzdanınızı boşaltabilir."],["governance-token","Yönetişim token'ı (governance token)","Yönetişim token'ı, sahiplerine bir protokolün veya DAO'nun kararlarında oy kullanma hakkı veren kripto token'ıdır; örneğin UNI, Uniswap yönetişiminde kullanılır."],["launchpool","Launchpool","Launchpool, borsanın belirli coin'leri veya stablecoin'leri havuzda kilitleyen kullanıcılara, yeni listelenecek bir projenin token'larını belirli bir süre boyunca ücretsiz dağıttığı programdır."],["rug-pull","Rug pull (halı çekme)","Rug pull, bir kripto projesinin geliştiricilerinin yatırımcı parasını toplayıp likiditeyi çekerek, token'ları satarak veya akıllı sözleşmedeki gizli yetkileri kullanarak projeyi aniden terk ettiği dolandırıcılıktır."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Biri sana para kazandıracağını söylüyor. Önce ne istediğine bak."},"coin":null,"tool":null,"cta":false},"centralized-exchange":{"slug":"centralized-exchange","cat":"trading","en":"Centralized exchange (CEX)","contentLocale":"tr","term":"Merkezi borsa (CEX)","aka":["CEX","merkezi kripto borsası","centralized exchange","borsa"],"short":"Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur.","body":["Binance, OKX, Bybit, Bitget ve Coinbase gibi platformlar merkezi borsalara örnektir. Bir CEX'e para yatırdığınızda coinlerin özel anahtarları borsadadır; siz borsanın kayıtlarındaki bakiyenizi görürsünüz. Bu, saklama (custodial) modelidir.",["Merkezi borsalar yüksek ",["likidite","liquidity"],", hızlı emir eşleştirme, itibari para yatırma-çekme, ",["vadeli işlemler","futures-contract"],", ",["staking","staking"]," ve ",["kopya işlem","copy-trading"]," gibi birçok hizmeti tek yerde sunar. Karşılığında kimlik doğrulaması (",["KYC","kyc"],") ister ve bulunduğunuz ülkenin düzenlemelerine tabidir. Türkiye'de ",["kripto varlık","cryptocurrency"]," hizmet sağlayıcılarının SPK'dan izin alması gerekir."],"Temel risk karşı taraf riskidir: borsa iflas eder, hacklenir veya çekimleri durdurursa fonlarınıza erişemeyebilirsiniz. Rezerv kanıtı (proof of reserves) yayımlayan borsalar biraz şeffaflık sağlar. Uzun süre tutmayı planladığınız varlıkları kendi cüzdanınıza çekmek bu riski azaltır."],"example":"Bir CEX'te 1.000 USDT ile 0,5 ETH aldığınızı düşünün (ETH 2.000 USDT). İşlem, borsanın emir defterinde başka bir kullanıcının satış emriyle anında eşleşir ve borsa yüzde 0,1 alıcı (taker) ücreti olarak 1 USDT keser. ETH'yi kendi cüzdanınıza çekerseniz borsa ayrıca bir çekim ücreti uygular. Aynı alımı bir merkeziyetsiz borsada yapsaydınız fonlar sizin cüzdanınızda kalırdı ama gas ücreti ve havuz ücreti öderdiniz. Hangi yolun ucuz olduğu, tutara ve ağın o anki yoğunluğuna bağlıdır.","mistakes":["Tüm birikimleri uzun süre tek bir borsada tutmak.","İki faktörlü doğrulama ve çekim adresi beyaz listesi gibi güvenlik ayarlarını açmamak.","Borsadan çekim yaparken alıcı cüzdanın desteklemediği bir ağ seçmek."],"faq":[{"q":"CEX ile DEX arasındaki fark nedir?","a":"CEX bir şirket tarafından işletilir ve fonlarınızı saklar. DEX ise akıllı kontratlarla çalışır ve fonlar işlem boyunca sizin cüzdanınızda kalır."},{"q":"Merkezi borsalar güvenli mi?","a":"Güvenlik borsaya, lisansına, rezerv şeffaflığına ve sizin hesap güvenliği ayarlarınıza bağlıdır. Saklama modelinde borsanın kendisi de bir risk unsurudur."}],"title":"Merkezi borsa (CEX) nedir? Nasıl çalışır?","description":"Merkezi kripto borsasının nasıl çalıştığını, DEX'ten farkını ve fonlarınızı borsada tutmanın karşı taraf riskini öğrenin.","related":[["dex","Merkeziyetsiz borsa (DEX)","Merkeziyetsiz borsa (DEX), kullanıcıların kendi cüzdanlarından, bir şirkete fon emanet etmeden, akıllı sözleşmeler aracılığıyla kripto takası yaptığı borsadır."],["kyc","KYC (müşterini tanı)","KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir."],["proof-of-reserves","Rezerv kanıtı (proof of reserves)","Rezerv kanıtı (PoR), bir kripto borsasının kullanıcılarına ait bakiyeleri karşılayacak kadar varlığı gerçekten tuttuğunu, zincir üstü adresler ve kriptografik yöntemlerle göstermeye çalıştığı denetim raporudur."],["custodial-wallet","Emanetçi cüzdan (Custodial wallet)","Emanetçi cüzdan (custodial wallet), kripto varlıklarınızın özel anahtarlarını sizin yerinize bir borsanın veya saklama kuruluşunun tuttuğu cüzdan türüdür."],["maker-taker-fees","Maker ve taker ücretleri","Maker ve taker ücretleri, borsanın emir defterine likidite ekleyen (maker) ve defterdeki emirleri anında karşılayarak likidite çeken (taker) işlemlere uyguladığı farklı komisyon oranlarıdır."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı"},"coin":null,"tool":"/exchanges","cta":true},"support-and-resistance":{"slug":"support-and-resistance","cat":"trading","en":"Support and resistance","contentLocale":"tr","term":"Destek ve direnç (Support and resistance)","aka":["destek seviyesi","direnç seviyesi","support","resistance"],"short":"Destek ve direnç, grafikte fiyatın daha önce düşüşünün (destek) veya yükselişinin (direnç) durduğu ve alıcılarla satıcıların yoğunlaştığı fiyat bölgeleridir.","body":[["Destek, alım talebinin fiyatın daha fazla düşmesini engellediği bölgedir. Direnç ise satış baskısının yükselişi frenlediği bölgedir. Bu seviyeler kesin çizgiler değil, genellikle birkaç yüzde genişliğinde bölgelerdir ve önceki dipler, tepeler, yuvarlak sayılar veya ",["tüm zamanların en yüksek seviyesi","all-time-high"]," gibi yerlerde oluşur."],"Bir direnç güçlü hacimle kırılırsa çoğu zaman yeni destek olarak çalışır; desteğin kırılması da onu dirence dönüştürebilir. Bir seviye ne kadar çok test edilmişse ve ne kadar uzun bir zaman diliminde görülüyorsa o kadar çok dikkat çeker.",["İşlemciler bu bölgeleri giriş, zarar durdur (",["stop-loss","stop-loss"],") ve kâr al seviyelerini planlamak için kullanır. Ancak çok sayıda stop emri aynı yerde toplandığı için seviyenin kısa süreliğine delinip geri dönmesi sık görülür."]],"example":[["BTC","bitcoin"]," son iki ayda üç kez 58.000 ",["USDT","usdt"]," civarına düşüp geri dönmüş, dört kez de 64.000 USDT civarında satışla karşılaşmış olsun. 58.000 destek, 64.000 direnç bölgesidir. 58.500'den alım yapıp stop'u desteğin biraz altına, 57.200'e koyarsanız birim başına riskiniz 1.300 USDT olur. Hedefi direncin hemen altına, 63.500'e koyarsanız olası kazanç 5.000 USDT'dir; ",["risk-ödül oranı","risk-reward-ratio"]," yaklaşık 1'e 3,8 olur."],"mistakes":["Destek ve direnci tek bir kesin fiyat sanıp stop'u tam seviyenin dibine koymak.","Bir seviyenin sonsuza kadar tutacağını varsaymak; her yeni test seviyeyi zayıflatabilir.","Kısa zaman dilimindeki küçük seviyeleri günlük ve haftalık seviyelerle aynı önemde görmek."],"faq":[{"q":"Destek kırılınca ne olur?","a":"Fiyat genellikle bir sonraki destek bölgesine doğru hareket eder ve kırılan seviye direnç gibi davranmaya başlayabilir. Kırılmanın mum kapanışı ve hacimle teyit edilmesi beklenir."},{"q":"Destek ve direnç nasıl çizilir?","a":"Önceki dip ve tepeleri birleştiren yatay bölgeler işaretlenir. Uzun zaman dilimlerinden başlayıp kısa zaman dilimlerine inmek daha güvenilir sonuç verir."}],"title":"Destek ve direnç nedir? Grafikte nasıl bulunur","description":"Destek ve direnç seviyelerinin nasıl oluştuğunu, kırılınca ne olduğunu ve stop planında nasıl kullanıldığını öğrenin.","related":[["candlestick-chart","Mum grafiği (Candlestick chart)","Mum grafiği, her zaman dilimi için açılış, en yüksek, en düşük ve kapanış fiyatını tek bir mum şeklinde gösteren fiyat grafiğidir."],["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."],["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir."],["all-time-high","Tüm zamanların en yüksek seviyesi (ATH)","Tüm zamanların en yüksek seviyesi (all-time high, ATH), bir kripto paranın işlem görmeye başladığından bu yana ulaştığı en yüksek fiyattır."]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"Tek bir mum: Size söylediği dört şey nedir?"},"coin":null,"tool":null,"cta":false},"dollar-cost-averaging":{"slug":"dollar-cost-averaging","cat":"trading","en":"Dollar-cost averaging (DCA)","contentLocale":"tr","term":"Düzenli alım stratejisi (DCA)","aka":["DCA","dollar-cost averaging","maliyet ortalaması","periyodik alım"],"short":"DCA (dollar-cost averaging), fiyatı tahmin etmeye çalışmadan belirli aralıklarla sabit tutarda kripto alarak ortalama maliyeti zamana yayma stratejisidir.","body":["DCA'da bütçenizi tek seferde yatırmak yerine, örneğin her hafta veya her ay aynı tutarla alım yaparsınız. Fiyat düşükken aynı parayla daha çok coin, yüksekken daha az coin alırsınız. Böylece tek bir kötü zamanlamanın etkisi azalır.","DCA kazanç garantisi değildir. Varlığın fiyatı uzun süre düşerse ortalama maliyetiniz de değer kaybeder. Sürekli yükselen bir piyasada tek seferlik alım bazen daha iyi sonuç verebilir; DCA'nın asıl faydası disiplin sağlaması ve duygusal karar verme riskini azaltmasıdır.","Birçok borsa otomatik yinelenen alım özelliği sunar. Küçük tutarlarla çok sık alım yaparken işlem ücretlerine ve kartla alımlarda oluşabilecek ek masraflara dikkat edin."],"example":["Her ay 100 ",["USDT","usdt"]," ile ",["BTC","bitcoin"]," aldığınızı düşünün. Ocakta fiyat 50.000, şubatta 40.000, martta 62.500 USDT olsun. Sırasıyla 0,002, 0,0025 ve 0,0016 BTC alırsınız; toplam 0,0061 BTC için 300 USDT ödemiş olursunuz. Ortalama maliyetiniz 300 / 0,0061 = yaklaşık 49.180 USDT'dir. Bu rakam, üç fiyatın basit ortalaması olan yaklaşık 50.833 USDT'den düşüktür, çünkü ucuz ayda daha fazla coin aldınız."],"mistakes":["DCA ile alınan her varlığın uzun vadede mutlaka kâra geçeceğini sanmak.","Çok küçük ve çok sık alımlarla işlem ücretlerinin getiriyi yemesine izin vermek.","Fiyat düşünce planı bırakıp yükselince yeniden başlamak; bu davranış DCA'nın amacını bozar."],"faq":[{"q":"DCA mı toplu alım mı daha iyi?","a":"Hangisinin daha iyi sonuç vereceği fiyatın sonraki seyrine bağlıdır ve önceden bilinemez. DCA zamanlama riskini yayar, toplu alım ise tüm parayı hemen piyasaya sokar."},{"q":"DCA ne sıklıkla yapılmalı?","a":"Haftalık veya aylık alım yaygındır. Önemli olan gelirinize uygun, sürdürebileceğiniz ve ücretlerin orantısız olmadığı bir sıklık seçmektir."}],"title":"DCA nedir? Düzenli alım stratejisi nasıl işler","description":"DCA stratejisinin nasıl çalıştığını, ortalama maliyetin nasıl hesaplandığını ve sınırlarını örnekle öğrenin.","related":[["hodl","HODL","HODL, kısa vadeli fiyat dalgalanmalarına rağmen kripto paraları satmadan uzun süre elde tutma stratejisini ifade eden, 2013'teki bir forum yazısındaki yazım hatasından doğmuş bir terimdir."],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir."],["position-sizing","Pozisyon büyüklüğü (Position sizing)","Pozisyon büyüklüğü, bir işleme ne kadar sermaye ayıracağınızı zarar durdur seviyenize ve kabul edebileceğiniz en yüksek kayba göre belirleme yöntemidir."],["grid-trading-bot","Grid trading botu (ızgara botu)","Grid trading botu, belirlediğiniz fiyat aralığını eşit basamaklara bölüp her basamakta otomatik alım ve satım emirleri vererek yatay piyasadaki dalgalanmalardan küçük kârlar toplayan bottur."],["spot-trading","Spot işlem (spot trading)","Spot işlem, bir kripto parayı o anki piyasa fiyatından alıp satarak varlığın kendisine anında sahip olduğunuz, kaldıraç ve vade içermeyen temel alım satım türüdür."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Ne kadar alacağınıza karar vermeden önce ne kadar kaybedebileceğinizi belirleyin"},"coin":null,"tool":null,"cta":true},"usdt-margined-futures":{"slug":"usdt-margined-futures","cat":"derivatives","en":"USDT-margined (linear) futures","contentLocale":"tr","term":"USDT teminatlı vadeli kontrat (USDT-margined futures)","aka":["USDT-M","doğrusal vadeli kontrat","linear futures","USDⓈ-M"],"short":"USDT teminatlı vadeli kontrat, teminatın USDT olarak yatırıldığı ve kâr-zararın doğrudan USDT cinsinden, fiyat hareketiyle doğrusal olarak hesaplandığı vadeli işlem sözleşmesidir.","body":[["Bu kontratlarda ",["pozisyon büyüklüğü","position-sizing"]," coin adedi olarak belirlenir ve her 1 ",["USDT","usdt"],"'lik fiyat hareketi, tuttuğunuz coin miktarı kadar USDT kâr veya zarar yaratır. Hesaplama basit ve doğrusal olduğu için yeni başlayanlar çoğunlukla bu tür kontratlarla başlar."],["Teminatınız stabil bir varlıkta durduğu için, coin teminatlı kontratlardaki gibi teminat değerinin fiyatla birlikte dalgalanması sorunu yoktur. Tek bir USDT bakiyesiyle ",["BTC","bitcoin"],", ",["ETH","ethereum"]," ve birçok ",["altcoin","altcoin"]," kontratında işlem yapabilirsiniz. Bazı borsalar ",["USDC","usdc"]," teminatlı benzer kontratlar da sunar."],"Çapraz marjin modunda aynı USDT bakiyesi tüm açık pozisyonlar için ortak teminat olarak kullanılır. Bu, bir pozisyondaki kaybın diğerlerinin teminatını da tüketebileceği anlamına gelir. Teminat varlığı olarak USDT'nin kendisinin de bir ihraççı riski taşıdığını unutmayın; USDT'yi Tether ihraç eder."],"example":"SOL 150 USDT iken USDT teminatlı kontratta 20 SOL long açıyorsunuz. Pozisyon değeri 3.000 USDT'dir ve 5x kaldıraçla 600 USDT teminat bağlarsınız. SOL 165'e çıkarsa kârınız 20 × 15 = 300 USDT, 135'e düşerse zararınız 20 × 15 = 300 USDT olur. Her iki yönde aynı büyüklükte fiyat hareketi aynı büyüklükte sonuç verir; coin teminatlı kontrattaki gibi teminat değeri ayrıca değişmez.","mistakes":["Çapraz marjinde tüm USDT bakiyesinin tek bir kötü pozisyon yüzünden risk altında olduğunu fark etmemek.","Coin adedi ile kontrat değerini karıştırıp istemeden çok büyük pozisyon açmak.","USDT ve USDC teminatlı kontratların ücret ve fonlama koşullarının aynı olduğunu varsaymak."],"faq":[{"q":"Yeni başlayan için USDT teminatlı mı coin teminatlı mı?","a":"USDT teminatlı kontratlarda kâr-zarar doğrusal ve USDT cinsinden olduğu için hesaplaması daha kolaydır. Coin teminatlı kontratlar daha çok elinde coin tutup hedge yapmak isteyenlere uygundur."},{"q":"USDT teminatlı kontratta fonlama var mı?","a":"Sürekli (perpetual) USDT teminatlı kontratlarda fonlama ödemeleri vardır. Teslimatlı USDT kontratlarında ise fonlama yoktur."}],"title":"USDT teminatlı vadeli kontrat nedir? USDT-M rehberi","description":"USDT teminatlı (doğrusal) vadeli kontratların nasıl çalıştığını ve coin teminatlı kontratlardan farkını öğrenin.","related":[["coin-margined-futures","Coin teminatlı vadeli kontrat (Coin-margined futures)","Coin teminatlı vadeli kontrat, teminatın ve kâr-zararın USDT yerine BTC veya ETH gibi dayanak coinin kendisiyle hesaplandığı ters (inverse) vadeli işlem sözleşmesidir."],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["usdt","USDT (Tether)","USDT (Tether), Tether şirketi tarafından çıkarılan, değerini 1 ABD dolarına sabitlemeyi amaçlayan ve kripto piyasalarında en yaygın kullanılan stablecoin'dir."],["cross-margin","Çapraz marjin (Cross margin)","Çapraz marjin, hesaptaki kullanılabilir bakiyenin tamamının tüm açık pozisyonlar için ortak teminat olarak kullanıldığı marjin modudur."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot ve vadeli işlemler: Aynı şeyi satın almıyorsunuz"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"open-interest":{"slug":"open-interest","cat":"derivatives","en":"Open interest","contentLocale":"tr","term":"Açık pozisyon miktarı (Open interest)","aka":["open interest","OI","açık pozisyon"],"short":"Açık pozisyon miktarı (open interest), bir vadeli işlem veya opsiyon piyasasında henüz kapatılmamış toplam kontrat sayısını ya da değerini gösterir.","body":["Her vadeli kontratın bir long ve bir short tarafı vardır. Yeni bir alıcı ve yeni bir satıcı eşleştiğinde açık pozisyon artar; iki taraf da pozisyon kapattığında azalır. Pozisyon bir kişiden diğerine geçerse açık pozisyon değişmez. Bu yüzden açık pozisyon, işlem hacminden farklı olarak piyasada şu anda ne kadar kaldıraçlı riskin durduğunu gösterir.","İşlemciler açık pozisyonu fiyatla birlikte yorumlar. Fiyat yükselirken açık pozisyonun da artması, yeni pozisyonların harekete katıldığını gösterir. Fiyat yükselirken açık pozisyonun düşmesi ise yükselişin daha çok short pozisyonların kapanmasından geldiğine işaret edebilir.",["Çok yüksek açık pozisyon, piyasada birikmiş ",["kaldıraç","leverage"]," demektir ve ani bir hareket zincirleme likidasyonlara yol açabilir. Açık pozisyon coin adedi veya dolar değeri olarak gösterilir; dolar bazlı rakam fiyat yükseldiğinde pozisyon sayısı değişmese bile artar."]],"example":[["BTC","bitcoin"]," ",["perpetual","perpetual-futures"]," kontratında açık pozisyon 100.000 BTC ve fiyat 60.000 ",["USDT","usdt"],"; dolar değeri 6 milyar USDT. Bir hafta sonra fiyat 63.000 USDT'ye çıkıyor ve açık pozisyon 112.000 BTC oluyor. Dolar değeri yaklaşık 7,06 milyar USDT'dir. Bu artışın yaklaşık 0,3 milyar USDT'si fiyat yükselişinden, yaklaşık 0,76 milyar USDT'si ise yeni açılan 12.000 BTC'lik pozisyonlardan gelir."],"mistakes":["Açık pozisyonu işlem hacmiyle karıştırmak.","Dolar bazlı açık pozisyon artışını, fiyat etkisini ayırmadan yeni pozisyon girişi sanmak.","Yüksek açık pozisyonu tek başına bir yön sinyali olarak kullanmak."],"faq":[{"q":"Açık pozisyon artarsa fiyat yükselir mi?","a":"Hayır, açık pozisyon tek başına yön göstermez. Hem long hem short taraf eşit büyür; yorumu fiyat hareketi ve fonlama oranıyla birlikte yapmak gerekir."},{"q":"Açık pozisyon ile hacim arasındaki fark nedir?","a":"Hacim belirli bir sürede gerçekleşen işlem miktarıdır. Açık pozisyon ise belirli bir anda kapatılmamış kontratların toplamıdır."}],"title":"Open interest (açık pozisyon) nedir? Nasıl yorumlanır","description":"Açık pozisyon miktarının ne olduğunu, hacimden farkını ve fiyatla birlikte nasıl yorumlandığını öğrenin.","related":[["trading-volume","İşlem hacmi (Trading volume)","İşlem hacmi, belirli bir sürede, genellikle 24 saatte, bir varlığın ne kadarının alınıp satıldığını gösteren toplam miktardır."],["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."],["long-short-ratio","Long/short oranı (Long/short ratio)","Long/short oranı, bir vadeli işlem piyasasında long pozisyon tutan hesapların veya pozisyonların short tarafına oranını gösteren bir piyasa duyarlılığı göstergesidir."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"hot-wallet":{"slug":"hot-wallet","cat":"wallets-security","en":"Hot wallet","contentLocale":"tr","term":"Sıcak cüzdan (hot wallet)","aka":["hot wallet","çevrimiçi cüzdan","sıcak cüzdan"],"short":"Sıcak cüzdan, özel anahtarları internete bağlı bir cihazda veya sunucuda tutulan, bu sayede hızlı işlem yapmaya uygun ama çevrim dışı saklamaya göre daha fazla saldırıya açık olan kripto cüzdanıdır.","body":[["Telefonunuzdaki cüzdan uygulamaları, tarayıcı eklentisi cüzdanlar ve borsaların günlük çekimler için kullandığı cüzdanlar sıcak cüzdan sayılır. Anahtar, internete bağlı bir ortamda bulunduğu için birkaç saniyede transfer yapabilir, ",["DeFi","defi"]," uygulamalarına bağlanabilir ve token takası yapabilirsiniz."],["Kolaylığın bedeli saldırı yüzeyidir. Kötü amaçlı yazılımlar, sahte tarayıcı eklentileri, ",["oltalama (phishing)","phishing"]," siteleri ve kandırılarak imzalatılan işlemler sıcak cüzdanları hedef alır. Cihaz ele geçirilirse anahtar da risk altına girer."],"Pratik bir yaklaşım, sıcak cüzdanı bir cüzdan gibi değil bir \"cep harçlığı\" gibi kullanmaktır: günlük işlem için gereken tutarı orada tutup büyük birikimi soğuk cüzdanda saklamak. Borsalar da benzer şekilde varlıklarının büyük kısmını soğuk depolamada, küçük bir kısmını çekimler için sıcak cüzdanlarda tutar."],"example":["Toplam 5.000 ",["USDT","usdt"]," değerinde kriptonuz olduğunu düşünün. Haftalık ",["DEX","dex"]," işlemleri için 400 USDT'yi telefonunuzdaki sıcak cüzdanda, kalan 4.600 USDT'yi donanım cüzdanında tuttuğunuzu varsayalım. Bir gün sahte bir ",["airdrop","airdrop"]," sitesinde yanlış bir onay verip sıcak cüzdanınız boşaltılsa bile kaybınız 400 USDT ile sınırlı kalır; portföyünüzün yaklaşık yüzde 92'si etkilenmez."],"mistakes":["Tüm birikimi tarayıcı eklentisi cüzdanında tutmak.","Aynı tarayıcıda çok sayıda doğrulanmamış eklenti kurmak.","Sıcak cüzdanın kurtarma ifadesini aynı cihazda not uygulamasına kaydetmek."],"faq":[{"q":"Sıcak cüzdan güvenli mi?","a":"Küçük ve günlük kullanılan tutarlar için makul bir seçimdir. Uzun vadeli büyük birikim için çevrim dışı saklama daha düşük risk taşır."},{"q":"Borsa hesabı sıcak cüzdan mıdır?","a":"Borsa hesabı saklamalı bir hesaptır; anahtarları borsa tutar. Borsalar çekimleri işlemek için kendi sıcak cüzdanlarını, rezervlerin çoğu için soğuk cüzdanları kullanır."}],"title":"Sıcak cüzdan (hot wallet) nedir? Anlamı ve riskleri","description":"Sıcak cüzdanın ne olduğunu, neden pratik ama daha riskli olduğunu ve ne kadar kripto tutmanın mantıklı olduğunu öğrenin.","related":[["cold-wallet","Soğuk cüzdan (cold wallet)","Soğuk cüzdan, özel anahtarları internete hiç bağlanmayan bir cihazda veya ortamda saklayarak uzaktan çalınma riskini büyük ölçüde azaltan kripto saklama yöntemidir."],["hardware-wallet","Donanım cüzdanı (hardware wallet)","Donanım cüzdanı, özel anahtarları güvenli bir çip içinde çevrim dışı saklayan ve işlemleri cihazın kendi ekranında onaylatarak imzalayan küçük bir fiziksel cihazdır."],["non-custodial-wallet","Saklama dışı cüzdan (non-custodial wallet)","Saklama dışı cüzdan, özel anahtarları yalnızca sizin kontrol ettiğiniz, bu yüzden fonlarınızı sizden başka kimsenin taşıyamadığı, donduramadığı veya sizin yerinize kurtaramadığı bir kripto cüzdanıdır."],["phishing","Oltalama (phishing)","Oltalama (phishing), dolandırıcıların sahte web siteleri, e-postalar, mesajlar veya reklamlar kullanarak sizden şifre, 2FA kodu, kurtarma ifadesi almaya ya da zararlı bir işlemi imzalatmaya çalıştığı saldırıdır."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı"},"coin":null,"tool":null,"cta":false},"seed-phrase":{"slug":"seed-phrase","cat":"wallets-security","en":"Seed phrase (recovery phrase)","contentLocale":"tr","term":"Kurtarma ifadesi (seed phrase)","aka":["seed phrase","gizli kurtarma ifadesi","anımsatıcı kelimeler","recovery phrase"],"short":"Kurtarma ifadesi (seed phrase), bir kripto cüzdanının tüm özel anahtarlarının türetildiği 12 veya 24 kelimelik listedir ve bu kelimeleri bilen herkes cüzdanın tamamını kontrol edebilir.","body":["Saklama dışı bir cüzdan oluşturduğunuzda uygulama, standart bir kelime listesinden rastgele seçilmiş 12, 18 veya 24 kelime üretir. Bu kelimelerden matematiksel olarak bir ana anahtar, ondan da her ağ ve hesap için ayrı özel anahtarlar türetilir. Yani tek bir ifade, birçok coinin ve adresin yedeğidir.","Telefonunuz bozulursa veya donanım cüzdanınız kaybolursa, bu kelimeleri aynı sırayla uyumlu bir cüzdana girerek her şeyi geri yükleyebilirsiniz. Tersine, birisi ifadenizi ele geçirirse cihazınıza hiç dokunmadan fonlarınızı başka bir adrese aktarabilir.","Bu nedenle gerçek bir cüzdan, borsa veya destek ekibi sizden asla kurtarma ifadesi istemez. İfadeyi isteyen bir web sitesi, \"cüzdan doğrulama\" formu ya da sohbet botu neredeyse her zaman dolandırıcılıktır. İfadeyi kâğıda veya metal plakaya yazıp çevrim dışı, güvenli bir yerde saklamak yaygın yöntemdir."],"example":["12 kelimelik bir ifadeyle iki ağda varlık tuttuğunuzu varsayalım: ",["Ethereum","ethereum"]," ağında 0,6 ETH ve Tron ağında 250 ",["USDT","usdt"],". Telefonunuz çalınır. Yeni bir telefona cüzdan uygulamasını kurup 12 kelimeyi doğru sırayla girdiğinizde hem 0,6 ETH'yi hem de 250 USDT'yi aynı adreslerde görürsünüz. Ama kelimelerden birini yanlış yazarsanız uygulama bambaşka, boş bir cüzdan açabilir; bu yüzden yazımı ve sırayı kontrol etmek önemlidir."],"mistakes":["Kurtarma ifadesini ekran görüntüsü, e-posta taslağı veya bulut notu olarak saklamak.","Cüzdan \"senkronizasyonu\" için ifadeyi isteyen bir siteye veya destek hesabına girmek.","Kelimeleri yazarken sırasını karıştırmak veya yedeği hiç test etmemek."],"faq":[{"q":"Kurtarma ifadesi ile özel anahtar aynı şey mi?","a":"Hayır. Kurtarma ifadesi, birçok özel anahtarın türetildiği ana yedektir. Bir özel anahtar genellikle tek bir adresi kontrol eder."},{"q":"Kurtarma ifademi kaybedersem ne olur?","a":"Cihazınız hâlâ çalışıyorsa hemen yeni bir cüzdan oluşturup fonları oraya taşıyabilirsiniz. Hem cihaz hem ifade kaybolursa fonlara erişmenin bir yolu yoktur."}],"title":"Kurtarma ifadesi (seed phrase) nedir? Nasıl saklanır?","description":"Seed phrase'in ne olduğunu, neden kimseyle paylaşılmaması gerektiğini ve güvenli yedekleme yöntemlerini öğrenin.","related":[["private-key","Özel anahtar (private key)","Özel anahtar, bir kripto adresindeki varlıkları harcamak için gereken dijital imzayı üreten gizli bir sayıdır ve onu bilen kişi o adresin fiilî sahibi olur."],["non-custodial-wallet","Saklama dışı cüzdan (non-custodial wallet)","Saklama dışı cüzdan, özel anahtarları yalnızca sizin kontrol ettiğiniz, bu yüzden fonlarınızı sizden başka kimsenin taşıyamadığı, donduramadığı veya sizin yerinize kurtaramadığı bir kripto cüzdanıdır."],["phishing","Oltalama (phishing)","Oltalama (phishing), dolandırıcıların sahte web siteleri, e-postalar, mesajlar veya reklamlar kullanarak sizden şifre, 2FA kodu, kurtarma ifadesi almaya ya da zararlı bir işlemi imzalatmaya çalıştığı saldırıdır."],["hardware-wallet","Donanım cüzdanı (hardware wallet)","Donanım cüzdanı, özel anahtarları güvenli bir çip içinde çevrim dışı saklayan ve işlemleri cihazın kendi ekranında onaylatarak imzalayan küçük bir fiziksel cihazdır."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Biri sana para kazandıracağını söylüyor. Önce ne istediğine bak."},"coin":null,"tool":null,"cta":false},"public-key":{"slug":"public-key","cat":"wallets-security","en":"Public key","contentLocale":"tr","term":"Açık anahtar (public key)","aka":["public key","genel anahtar"],"short":"Açık anahtar, özel anahtardan matematiksel olarak türetilen, imzaların doğrulanmasına yarayan ve genellikle cüzdan adresinin üretilmesinde kullanılan paylaşılabilir anahtardır.","body":[["Kripto paralar açık anahtarlı şifreleme kullanır. ",["Özel anahtar","private-key"]," gizli kalır ve işlemleri imzalar; açık anahtar ise herkesin görebileceği şekilde bu imzanın gerçekten o anahtarın sahibine ait olduğunu doğrular. Bu tek yönlü bir ilişkidir: açık anahtardan özel anahtar hesaplanamaz."],["Günlük kullanımda açık anahtarı nadiren doğrudan görürsünüz. ",["Bitcoin","bitcoin"]," ve ",["Ethereum","ethereum"]," gibi ağlarda adres, açık anahtarın hash fonksiyonlarından geçirilip kısaltılmış hâlidir. Bu yüzden insanlar para almak için açık anahtarı değil, adresi paylaşır."],"Bitcoin'deki genişletilmiş açık anahtar (xpub) gibi özel formatlar, bir cüzdanın tüm adreslerini türetebilir. Bu, para çalınmasına izin vermez ama tüm bakiye ve işlem geçmişinizi gösterebilir. Gizlilik açısından xpub'ı yalnızca güvendiğiniz muhasebe veya izleme araçlarıyla paylaşmak daha doğrudur."],"example":["Bir arkadaşınıza 0,02 BTC göndermesi için adresinizi verdiğinizi düşünün. Para ulaşır. Daha sonra bu adresten 0,01 BTC harcadığınızda cüzdanınız işlemi özel anahtarla imzalar ve işleme açık anahtarınızı ekler. Ağdaki binlerce ",["düğüm","node"],", yalnızca bu açık anahtara ve imzaya bakarak işlemin geçerli olduğunu kontrol eder; hiçbiri özel anahtarınızı görmez. Arkadaşınız da açık anahtarınızı bilse bile kalan 0,01 BTC'yi harcayamaz."],"mistakes":["Açık anahtar ile özel anahtarı karıştırıp gizli olanı paylaşmak.","xpub'ı herkese açık paylaşmanın gizliliği etkilemediğini düşünmek.","Açık anahtarı adres sanıp transfer alanına yapıştırmak."],"faq":[{"q":"Açık anahtar ile cüzdan adresi aynı mı?","a":"Çoğu ağda adres, açık anahtardan türetilen daha kısa bir değerdir. Para almak için adresi paylaşırsınız."},{"q":"Açık anahtarımı paylaşmak tehlikeli mi?","a":"Fonlarınızı çalmaya yetmez, çünkü imza için özel anahtar gerekir. Ancak bazı formatlar tüm adreslerinizi ortaya koyarak gizliliğinizi azaltabilir."}],"title":"Açık anahtar (public key) nedir? Kriptoda anlamı","description":"Açık anahtarın özel anahtar ve cüzdan adresiyle ilişkisini, imzaların nasıl doğrulandığını ve gizlilik etkisini öğrenin.","related":[["private-key","Özel anahtar (private key)","Özel anahtar, bir kripto adresindeki varlıkları harcamak için gereken dijital imzayı üreten gizli bir sayıdır ve onu bilen kişi o adresin fiilî sahibi olur."],["wallet-address","Cüzdan adresi (wallet address)","Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür."],["blockchain","Blockchain (blok zinciri)","Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Transferden önce: Bunların hiçbirini tahminle yapma"},"coin":null,"tool":null,"cta":false},"transaction-hash":{"slug":"transaction-hash","cat":"wallets-security","en":"Transaction hash (TxID)","contentLocale":"tr","term":"İşlem hash'i (TxID)","aka":["TxID","transaction hash","işlem kimliği","tx hash"],"short":"İşlem hash'i (TxID), blokzincire gönderilen her işleme verilen benzersiz kimlik kodudur ve işlemin durumunu bir blok gezgininde takip etmenizi sağlar.","body":["Bir transfer ağa yayınlandığında işlem verisi bir hash fonksiyonundan geçirilir ve uzun bir harf-rakam dizisi elde edilir. Bu dizi işlemin parmak izi gibidir. Borsalar çekim geçmişinde bu kodu TxID veya Hash olarak gösterir.",["TxID'yi o ağın blok gezginine (",["Bitcoin","bitcoin"]," için ",["Mempool","mempool"],", ",["Ethereum","ethereum"]," için Etherscan, Tron için Tronscan gibi) yapıştırdığınızda işlemin bekleyip beklemediğini, kaç onay aldığını, gönderilen tutarı, ücreti ve ",["alıcı adresi","wallet-address"]," görebilirsiniz."],"Transferiniz gecikirse destek ekiplerinin ilk istediği şey TxID'dir. Gezgin işlemin başarılı olduğunu ve doğru adrese gittiğini gösteriyorsa sorun büyük olasılıkla alıcı tarafın yatırma işleminde veya eksik memo'dadır. TxID hiç yoksa çekim henüz borsadan çıkmamış olabilir."],"example":"Borsadan cüzdanınıza 0,3 ETH çektiniz ama 20 dakika sonra hâlâ görünmüyor. Çekim geçmişinde TxID'yi kopyalayıp Etherscan'e yapıştırıyorsunuz. Gezgin işlemin \"Success\" durumunda olduğunu, 0,3 ETH'nin gönderildiğini ve alıcı adresin sizin cüzdanınızla eşleştiğini gösteriyor. Bu durumda sorun cüzdan uygulamanızın yanlış ağı göstermesidir; ağ ayarını Ethereum ana ağına çevirdiğinizde 0,3 ETH görünür.","mistakes":["TxID'yi farklı bir ağın blok gezgininde aramak ve işlem yok sanmak.","Destek talebinde TxID yerine yalnızca ekran görüntüsü göndermek.","TxID'yi paylaşmanın hesabı tehlikeye attığını sanmak; TxID herkese açık bir kayıttır."],"faq":[{"q":"TxID nerede bulunur?","a":"Borsanın çekim veya yatırma geçmişinde, işlem detayında yer alır. Cüzdan uygulamaları da gönderilen her işlem için TxID gösterir."},{"q":"TxID var ama para gelmedi, ne yapmalıyım?","a":"Gezginde işlemin başarılı olduğunu, doğru adres ve ağı kontrol edin. Her şey doğruysa alıcı borsanın destek ekibine TxID ile başvurun."}],"title":"TxID (işlem hash'i) nedir? Transfer nasıl takip edilir?","description":"İşlem hash'inin (TxID) ne olduğunu, blok gezgininde nasıl arandığını ve geciken transferlerde nasıl kullanıldığını öğrenin.","related":[["block-explorer","Blok gezgini (block explorer)","Blok gezgini, bir blockchain'deki işlemleri, adresleri ve blokları herkesin arama yapıp görebileceği şekilde listeleyen web tabanlı bir araçtır."],["block-confirmations","Blok onayı (confirmation)","Blok onayı, bir işlemin bir bloğa eklenmesinden sonra üzerine eklenen her yeni bloğu ifade eder; onay sayısı arttıkça işlemin geri alınması pratikte imkânsız hâle gelir."],["blockchain-network","Yatırma ağı (ağ seçimi)","Yatırma ağı, bir kripto varlığı transfer ederken işlemin hangi blokzincir üzerinden gideceğini belirleyen seçimdir; gönderen ve alan tarafın aynı ağı desteklemesi gerekir."],["mempool","Mempool (bekleyen işlem havuzu)","Mempool, gönderilmiş ama henüz bir bloğa eklenmemiş işlemlerin, madenciler veya doğrulayıcılar tarafından seçilmeyi beklediği bekleme alanıdır."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Gönderildi yazıyor ama ulaşmadı. Nereye bakmalısın?"},"coin":null,"tool":null,"cta":false},"address-poisoning":{"slug":"address-poisoning","cat":"wallets-security","en":"Address poisoning","contentLocale":"tr","term":"Adres zehirleme (address poisoning)","aka":["address poisoning","adres zehirlenmesi","benzer adres dolandırıcılığı"],"short":"Adres zehirleme, dolandırıcının sizin sık kullandığınız adrese benzeyen bir adresten işlem geçmişinize küçük veya sıfır tutarlı transferler göndererek, bir sonraki transferinizde yanlış adresi kopyalamanızı sağlamaya çalıştığı saldırıdır.","body":["Birçok kullanıcı adresi uzun olduğu için yalnızca ilk ve son birkaç karakterine bakar. Saldırganlar, bilgisayar gücüyle baş ve son karakterleri sizin gerçek alıcınızın adresiyle aynı olan adresler üretir. Ardından bu sahte adresten cüzdanınıza önemsiz bir transfer yollar ya da sahte bir token transferi kaydı oluşturur.",["Bu işlem sizin işlem geçmişinizde gerçek adresin hemen yanında görünür. Bir sonraki sefer geçmişten adres kopyaladığınızda yanlış satırı seçerseniz, paranızı doğrudan saldırgana gönderirsiniz. ",["Blokzincir","blockchain"]," işlemleri geri alınamadığı için bu hata telafi edilemez."],"Korunma yolu basittir: adresleri işlem geçmişinden kopyalamamak, cüzdanın adres defterini veya borsanın çekim beyaz listesini kullanmak ve büyük transferlerden önce adresin ortasındaki karakterleri de kontrol etmektir."],"example":["Her ay ortağınıza 5.000 ",["USDT","usdt"]," gönderiyorsunuz; adresi 0x7aB2 ile başlıyor, 91Fc ile bitiyor. Bir gün işlem geçmişinizde aynı başlangıç ve bitişe sahip bir adresten gelen 0 USDT'lik bir transfer görüyorsunuz. Ortası tamamen farklı. Bir sonraki ödemede geçmişten bu adresi kopyalarsanız 5.000 USDT saldırgana gider. Adres defterinize kaydettiğiniz gerçek adresi kullanırsanız tuzağa düşmezsiniz."],"mistakes":["Adreslerin yalnızca ilk ve son 4 karakterini kontrol etmek.","Cüzdan veya gezgin işlem geçmişinden adres kopyalamak.","Gelen sıfır tutarlı veya tanımadığınız token transferlerini zararsız sanmak."],"faq":[{"q":"Adres zehirleme cüzdanımın hacklendiği anlamına mı gelir?","a":"Hayır. Saldırgan cüzdanınıza erişmez; yalnızca geçmişinize sahte kayıt ekler. Risk, sizin yanlış adresi kopyalamanızdır."},{"q":"Zehirli işlemleri silebilir miyim?","a":"Blokzincir kayıtları silinemez. Bazı cüzdanlar şüpheli işlemleri gizler; en iyi önlem adres defteri veya beyaz liste kullanmaktır."}],"title":"Adres zehirleme nedir? Benzer adres tuzağından korunma","description":"Adres zehirleme saldırısının nasıl çalıştığını, işlem geçmişinden adres kopyalamanın riskini ve korunma yollarını öğrenin.","related":[["wallet-address","Cüzdan adresi (wallet address)","Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür."],["withdrawal-whitelist","Çekim beyaz listesi (withdrawal whitelist)","Çekim beyaz listesi, borsa hesabınızdan yalnızca önceden kaydedip onayladığınız adreslere kripto çekilmesine izin veren bir güvenlik ayarıdır."],["phishing","Oltalama (phishing)","Oltalama (phishing), dolandırıcıların sahte web siteleri, e-postalar, mesajlar veya reklamlar kullanarak sizden şifre, 2FA kodu, kurtarma ifadesi almaya ya da zararlı bir işlemi imzalatmaya çalıştığı saldırıdır."],["transaction-hash","İşlem hash'i (TxID)","İşlem hash'i (TxID), blokzincire gönderilen her işleme verilen benzersiz kimlik kodudur ve işlemin durumunu bir blok gezgininde takip etmenizi sağlar."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Transferden önce: Bunların hiçbirini tahminle yapma"},"coin":null,"tool":null,"cta":false},"token-approval":{"slug":"token-approval","cat":"wallets-security","en":"Token approval (allowance)","contentLocale":"tr","term":"Token onayı (token approval / allowance)","aka":["token approval","allowance","harcama izni","sözleşme onayı"],"short":"Token onayı, cüzdanınızdaki belirli bir token'ı sizin adınıza harcayabilmesi için bir akıllı sözleşmeye verdiğiniz izindir ve sınırsız verilen onaylar istismar edilirse cüzdanınızı boşaltabilir.","body":[["ERC20 gibi token standartlarında bir ",["DEX","dex"]," veya ",["DeFi","defi"]," protokolü token'larınızı kullanmadan önce sizden onay ister. Bu, \"bu sözleşme benim ",["USDC","usdc"],"'mden şu kadarını harcayabilir\" anlamına gelen ayrı bir işlemdir. Onay verdikten sonra asıl takas veya yatırma işlemi yapılır."],"Birçok uygulama kolaylık için sınırsız onay ister; böylece her işlemde yeniden onay vermeniz gerekmez. Ancak o sözleşme hacklenirse veya baştan kötü niyetli bir siteye onay verdiyseniz, saldırgan izin verdiğiniz token'ın tamamını istediği zaman çekebilir. Onay, siz iptal edene kadar geçerli kalır.",["Cüzdanınızın onay penceresinde harcama limitini düşürebilir veya yalnızca işlem için gereken tutarı onaylayabilirsiniz. Ayrıca blok gezginlerinin onay kontrol araçları veya özel onay yönetim araçlarıyla eski onayları görüp iptal edebilirsiniz; iptal işlemi de küçük bir ",["ağ ücreti","gas-fee"]," gerektirir."]],"example":["Bir DEX'te 200 USDC'yi ",["ETH","ethereum"],"'ye çevirmek istiyorsunuz. Uygulama sınırsız USDC onayı istiyor. Onay limitini 200 USDC olarak düzenlersiniz. Aylar sonra o DEX'in eski bir sözleşmesi istismar edilse bile, sizin onayınız zaten kullanılmış olduğu için cüzdanınızdaki 4.000 USDC etkilenmez. Sınırsız onay verseydiniz bu 4.000 USDC'nin tamamı risk altında olurdu."],"mistakes":["Tanımadığınız sitelerde sınırsız onayı okumadan vermek.","Artık kullanmadığınız protokollere verilmiş eski onayları hiç iptal etmemek.","Onayın işlem bittikten sonra kendiliğinden sona erdiğini sanmak."],"faq":[{"q":"Token onayı nasıl iptal edilir?","a":"Blok gezgininin onay kontrol sayfası veya onay yönetim araçlarıyla cüzdanınızı bağlayıp ilgili onayı sıfırlarsınız. Bu bir işlemdir ve ağ ücreti gerektirir."},{"q":"Sadece onay vermek para kaybettirir mi?","a":"Onay tek başına fon taşımaz, ama izin verilen sözleşmenin daha sonra token'larınızı çekmesine olanak tanır. Kötü niyetli bir sözleşmeye verilen onay bu yüzden tehlikelidir."}],"title":"Token onayı (approval) nedir? Sınırsız onay riski","description":"Token onayının ne olduğunu, sınırsız allowance riskini ve eski onayları nasıl kontrol edip iptal edeceğinizi öğrenin.","related":[["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."],["phishing","Oltalama (phishing)","Oltalama (phishing), dolandırıcıların sahte web siteleri, e-postalar, mesajlar veya reklamlar kullanarak sizden şifre, 2FA kodu, kurtarma ifadesi almaya ya da zararlı bir işlemi imzalatmaya çalıştığı saldırıdır."],["non-custodial-wallet","Saklama dışı cüzdan (non-custodial wallet)","Saklama dışı cüzdan, özel anahtarları yalnızca sizin kontrol ettiğiniz, bu yüzden fonlarınızı sizden başka kimsenin taşıyamadığı, donduramadığı veya sizin yerinize kurtaramadığı bir kripto cüzdanıdır."],["dex","Merkeziyetsiz borsa (DEX)","Merkeziyetsiz borsa (DEX), kullanıcıların kendi cüzdanlarından, bir şirkete fon emanet etmeden, akıllı sözleşmeler aracılığıyla kripto takası yaptığı borsadır."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Biri sana para kazandıracağını söylüyor. Önce ne istediğine bak."},"coin":null,"tool":null,"cta":false},"dex":{"slug":"dex","cat":"defi","en":"Decentralized exchange (DEX)","contentLocale":"tr","term":"Merkeziyetsiz borsa (DEX)","aka":["DEX","decentralized exchange","merkeziyetsiz borsa"],"short":"Merkeziyetsiz borsa (DEX), kullanıcıların kendi cüzdanlarından, bir şirkete fon emanet etmeden, akıllı sözleşmeler aracılığıyla kripto takası yaptığı borsadır.","body":[["Merkezi borsada (",["CEX","centralized-exchange"],") parayı borsaya yatırır, borsanın emir defterinde işlem yaparsınız. DEX'te ise varlıklar işlem anına kadar sizin cüzdanınızda kalır. Uniswap, PancakeSwap ve Curve gibi DEX'lerin çoğu ",["otomatik piyasa yapıcı (AMM)","amm"]," modeliyle ",["likidite","liquidity"]," havuzları kullanır; Hyperliquid gibi bazıları ise zincir üstü ",["emir defteri","order-book"]," çalıştırır."],["DEX'lerin avantajı ",["kimlik doğrulama","kyc"]," gerektirmemesi ve yeni token'ların çok hızlı listelenebilmesidir. Bu aynı zamanda bir risktir: herkes token çıkarıp havuz açabildiği için sahte ve dolandırıcı token'lar da kolayca listelenir."],["Maliyetler de farklıdır. DEX'te havuz ücreti, ",["ağ ücreti","gas-fee"]," (gas) ve fiyat kayması (slippage) ödersiniz. Ayrıca işlemler herkese açık bekleme alanında göründüğü için önden işlem yapan botlar (MEV) sonucunuzu kötüleştirebilir. Bu yüzden kayma toleransını makul tutmak önemlidir."]],"example":"Bir DEX'te 2.000 USDC'yi ETH'ye çevirdiğinizi varsayalım. ETH fiyatı 2.500 USDC, havuz ücreti yüzde 0,3. Ücret 6 USDC olur ve 1.994 USDC takasa girer. İşlem büyüklüğü nedeniyle fiyat kayması yüzde 0,2 ise, yaklaşık 0,7976 yerine 0,7960 ETH alırsınız. Üstüne örneğin 2 USDC değerinde ağ ücreti ödersiniz. Kayma toleransını yüzde 0,5 ayarladığınız için fiyat daha fazla kötüleşseydi işlem geri çevrilirdi.","mistakes":["Token'ı sözleşme adresini doğrulamadan sadece adına bakarak almak.","Kayma toleransını yüzde 10 gibi çok yüksek bırakmak.","Ağ ücretini hesaba katmadan küçük tutarlarla takas yapmak."],"faq":[{"q":"DEX mi CEX mi daha güvenli?","a":"Farklı riskler taşırlar. DEX'te borsa iflası riski yoktur ama sözleşme hataları ve kullanıcı hataları riski vardır; CEX'te saklama riski vardır ama hesap kurtarma ve destek imkânı bulunur."},{"q":"DEX kullanmak için KYC gerekir mi?","a":"Çoğu DEX kimlik doğrulaması istemez. Ancak yerel düzenlemeler ve bazı ön yüz sitelerinin kısıtlamaları ülkeye göre değişebilir."}],"title":"DEX nedir? Merkeziyetsiz borsa nasıl çalışır?","description":"Merkeziyetsiz borsanın nasıl çalıştığını, CEX'ten farkını, DEX ücretlerini ve kayma toleransının önemini öğrenin.","related":[["amm","Otomatik piyasa yapıcı (AMM)","Otomatik piyasa yapıcı (AMM), alıcı ve satıcıları bir emir defterinde eşleştirmek yerine, likidite havuzundaki token oranlarına göre fiyatı bir formülle belirleyen ve takası doğrudan havuzla yaptıran DEX modelidir."],["centralized-exchange","Merkezi borsa (CEX)","Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur."],["liquidity-pool","Likidite havuzu (liquidity pool)","Likidite havuzu, kullanıcıların yatırdığı iki veya daha fazla token'ın bir akıllı sözleşmede kilitlendiği ve DEX'lerde takasların doğrudan bu havuzdan yapıldığı fon havuzudur."],["slippage","Kayma (slippage)","Kayma (slippage), bir emrin beklenen fiyat ile gerçekte gerçekleştiği ortalama fiyat arasındaki farktır ve genellikle piyasa emirlerinde, düşük likiditede veya hızlı fiyat hareketlerinde ortaya çıkar."],["perp-dex","Perp DEX (zincir üstü sürekli vadeli işlemler)","Perp DEX, sürekli (perpetual) vadeli kontratların kendi cüzdanınızdan, merkezi bir borsaya fon emanet etmeden, akıllı sözleşmeler veya kendi blokzinciri üzerinde işlem gördüğü merkeziyetsiz borsadır."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":"/compare","cta":false},"flash-loan":{"slug":"flash-loan","cat":"defi","en":"Flash loan","contentLocale":"tr","term":"Flaş kredi (flash loan)","aka":["flash loan","anlık kredi","flaş borç"],"short":"Flaş kredi, teminat gerektirmeyen ama aynı blokzincir işlemi içinde alınıp geri ödenmesi zorunlu olan bir DeFi borcudur; geri ödenmezse tüm işlem iptal edilir.","body":["Normal bir kredide geri ödeme riskini teminat karşılar. Flaş kredide ise risk, işlemin atomik olmasıyla çözülür: borç alma, kullanma ve geri ödeme tek bir işlemin adımlarıdır. Son adımda borç ve ücret ödenmezse işlem hiç gerçekleşmemiş gibi geri alınır. Aave gibi protokoller bu özelliği sunar.",["Flaş krediler genellikle geliştiriciler ve botlar tarafından kullanılır: ",["DEX","dex"],"'ler arası ",["arbitraj","arbitrage"],", teminat değiştirme veya tasfiye edilmek üzere olan bir pozisyonu kendi kendine kapatma gibi işlemler için. Bunları yapmak için ",["akıllı sözleşme","smart-contract"]," yazmak veya özel araçlar kullanmak gerekir."],"Flaş krediler kötüye de kullanılır. Saldırganlar büyük bir tutarı anlık olarak borç alıp düşük likiditeli bir havuzun fiyatını manipüle eder, bu fiyata güvenen bir protokolü istismar eder ve borcu aynı işlemde öder. Asıl açık genellikle flaş kredide değil, manipüle edilebilir fiyat kaynağı kullanan protokoldedir."],"example":["Bir token A DEX'inde 1,00 ",["USDC","usdc"],", B DEX'inde 1,01 USDC fiyatla işlem görüyor. Bir bot 100.000 USDC flaş kredi alır, A'da token alır, B'de satar. ",["Kayma","slippage"]," ve ücretler olmasaydı 1.000 USDC fark oluşurdu. Kredi ücreti örneğin yüzde 0,05 yani 50 USDC, DEX ücretleri ve kayma 600 USDC tutarsa net kâr yaklaşık 350 USDC olur. Kârın ücretleri karşılamadığı durumda işlem geri alınır ve yalnızca ",["ağ ücreti","gas-fee"]," kaybedilir."],"mistakes":["Flaş kredinin bedava para veya garantili kâr olduğunu sanmak.","Flaş kredi \"botu\" satan sosyal medya tekliflerine güvenmek; bunlar sıkça dolandırıcılıktır.","Başarısız işlemlerde bile ağ ücreti ödendiğini unutmak."],"faq":[{"q":"Flaş kredi neden teminat istemez?","a":"Borç aynı işlem içinde geri ödenmezse işlem bütünüyle iptal edilir. Bu yüzden borç verenin parası hiçbir zaman geri dönmeme riskiyle karşılaşmaz."},{"q":"Sıradan bir kullanıcı flaş kredi kullanabilir mi?","a":"Teknik olarak evet, ancak genellikle akıllı sözleşme bilgisi gerekir. Bazı araçlar bunu kolaylaştırır, ama riskleri ve maliyetleri anlamak şarttır."}],"title":"Flaş kredi (flash loan) nedir? Nasıl çalışır?","description":"Flaş kredinin teminatsız ama tek işlemde geri ödenen yapısını, kullanım alanlarını ve saldırılarda nasıl kullanıldığını öğrenin.","related":[["defi-lending","DeFi borç verme (DeFi lending)","DeFi borç verme, kullanıcıların kripto varlıklarını akıllı sözleşme havuzlarına yatırarak faiz kazandığı, başkalarının da bu havuzlardan teminat göstererek borç aldığı merkeziyetsiz kredi sistemidir."],["oracle","Blokzincir oracle'ı (kâhin)","Blokzincir oracle'ı, fiyatlar veya hava durumu gibi blokzincir dışındaki verileri akıllı sözleşmelere güvenilir biçimde taşıyan hizmettir; DeFi protokolleri teminat ve tasfiye hesaplarında bu verilere dayanır."],["mev","MEV (maksimum çıkarılabilir değer)","MEV (maksimum çıkarılabilir değer), blok üreticilerinin ve botların bir bloktaki işlemlerin sırasını belirleyerek, ekleyerek veya çıkararak elde edebildiği ek kârdır."],["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"wrapped-token":{"slug":"wrapped-token","cat":"defi","en":"Wrapped token","contentLocale":"tr","term":"Sarılmış token (wrapped token)","aka":["wrapped token","WBTC","WETH","sarmalanmış token"],"short":"Sarılmış token, başka bir varlığı birebir temsil eden ve onu farklı bir blokzincirde veya farklı bir token standardında kullanılabilir hâle getiren token'dır; örneğin WBTC, Ethereum'da Bitcoin'i temsil eder.","body":[[["Bitcoin","bitcoin"]," doğrudan ",["Ethereum","ethereum"],"'daki ",["DeFi","defi"]," uygulamalarında kullanılamaz. WBTC gibi yapılarda bir saklayıcı gerçek BTC'yi tutar ve Ethereum'da aynı miktarda WBTC basar. Böylece BTC sahipleri Ethereum'daki borç verme veya ",["likidite","liquidity"]," protokollerine katılabilir. Farklı sarılmış BTC türleri farklı saklama modelleri kullanır."],"WETH ise biraz farklıdır: ETH zaten Ethereum'dadır ama ERC20 standardına uymaz. WETH sözleşmesi ETH'yi kilitleyip ERC20 uyumlu bir token verir; bu tamamen akıllı sözleşmeyle yapılır ve bir saklayıcıya bağlı değildir.","Sarılmış token'ın değeri, arkasındaki varlığın gerçekten tutulmasına ve geri alınabilmesine dayanır. Saklayıcı, köprü veya sözleşme sorun yaşarsa sarılmış token temsil ettiği varlıktan düşük fiyatlanabilir. Bu yüzden hangi kuruluşun veya mekanizmanın arkada durduğunu bilmek önemlidir."],"example":["0,5 BTC'nizi Ethereum'da teminat olarak kullanmak istiyorsunuz. Bir borsada BTC'yi WBTC'ye çevirir ve Ethereum ağından cüzdanınıza çekersiniz; ",["çekim ücreti","withdrawal-fee"]," örneğin 0,0002 WBTC ise cüzdanınıza 0,4998 WBTC ulaşır. Bu WBTC'yi bir borç verme protokolüne yatırıp karşılığında ",["USDC","usdc"]," borç alabilirsiniz. İşiniz bitince WBTC'yi tekrar BTC'ye çevirip Bitcoin ağına çekebilirsiniz; her adımda ücretleri hesaba katmalısınız."],"mistakes":["WBTC'yi doğrudan bir Bitcoin adresine göndermeye çalışmak.","Farklı sarılmış BTC türlerinin aynı saklama modelini kullandığını sanmak.","Sarılmış token'ın sözleşme adresini doğrulamadan DEX'te almak."],"faq":[{"q":"WBTC ile BTC aynı mı?","a":"Değerce BTC'yi takip etmesi amaçlanır, ama farklı bir ağda çalışan ayrı bir token'dır ve saklayıcı riskini taşır."},{"q":"WETH neden gerekli?","a":"Birçok DeFi sözleşmesi yalnızca ERC20 token'larıyla çalışır. WETH, ETH'yi bu standarda uyumlu hâle getirir ve istendiğinde birebir ETH'ye çevrilebilir."}],"title":"Wrapped token nedir? WBTC ve WETH ne işe yarar?","description":"Sarılmış token'ların nasıl çalıştığını, WBTC ve WETH farkını ve saklayıcı ile depeg risklerini öğrenin.","related":[["cross-chain-bridge","Zincirler arası köprü (cross-chain bridge)","Zincirler arası köprü, bir kripto varlığı bir blokzincirden diğerine taşımanızı sağlayan ve genellikle varlığı kaynak zincirde kilitleyip hedef zincirde bir karşılığını çıkararak çalışan protokoldür."],["liquid-staking","Likit staking (liquid staking)","Likit staking, coinlerinizi stake ederken karşılığında stake edilen pozisyonu temsil eden ve alınıp satılabilen bir token (örneğin stETH) almanızı sağlayan staking yöntemidir."],["coin-vs-token","Coin ve token farkı","Coin, kendi blockchain'inin yerel varlığıdır (BTC, ETH, SOL gibi); token ise başka bir blockchain üzerinde akıllı kontratla oluşturulan varlıktır (Ethereum üzerindeki USDT veya UNI gibi)."],["depeg","Depeg (sabitin kopması)","Depeg, bir stablecoin'in bağlı olduğu değerden, örneğin 1 dolardan, belirgin ve kalıcı biçimde uzaklaşmasıdır; coin artık hedef fiyatında işlem görmez."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"kyc":{"slug":"kyc","cat":"regulation","en":"KYC (know your customer)","contentLocale":"tr","term":"KYC (müşterini tanı)","aka":["KYC","kimlik doğrulama","müşterini tanı","hesap doğrulama"],"short":"KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir.","body":[["Bir borsada hesap açtığınızda genellikle kimlik kartı veya pasaport fotoğrafı, yüz doğrulaması (selfie veya video) ve bazen adres belgesi istenir. Bu, ",["kara para aklamayı önleme","aml"]," (AML) kurallarının bir parçasıdır. Türkiye'de 2024'te yapılan yasal düzenlemeyle ",["kripto varlık","cryptocurrency"]," hizmet sağlayıcıları SPK lisansına tabi hâle geldi ve kimlik doğrulama yükümlülükleri netleşti."],"KYC çoğu borsada seviyelidir. Temel seviye sınırlı yatırma ve çekim izni verir; daha yüksek seviye için ek belgeler gerekir. Kurallar ülkeye ve borsaya göre değişir.","Kimlik verinizi kime verdiğiniz önemlidir. Yalnızca resmi uygulama veya web sitesi üzerinden yükleme yapın, belgelerinizi sohbet uygulamalarında 'destek' diye yazan kişilere göndermeyin. Gerçek borsalar KYC için şifrenizi veya kurtarma ifadenizi asla istemez."],"example":["Bir borsada temel KYC seviyesinin günlük 2.000 dolar, gelişmiş seviyenin ise 100.000 dolar çekim limiti sunduğunu varsayalım. Siz yalnızca kimlik ve selfie yüklediniz. Bir gün 5.000 dolarlık ",["USDT","usdt"]," çekmek istediğinizde işlem reddedilir; ya 3 güne bölerek çekmeniz ya da adres belgesi yükleyip gelişmiş seviyeye geçmeniz gerekir. Belge incelemesi birkaç saat ile birkaç gün sürebileceği için büyük çekimlerden önce seviyenizi tamamlamak işinizi kolaylaştırır."],"mistakes":["Kimlik belgelerini resmi kanal dışında, mesajla gönderilen bağlantılara yüklemek.","Başkası adına KYC yapmak veya hesabınızı başkasına kullandırmak.","Büyük bir transferden hemen önce KYC seviyesini kontrol etmemek."],"faq":[{"q":"KYC yapmadan kripto alınabilir mi?","a":"Merkezi borsaların çoğu alım satım veya çekim için KYC ister. Merkeziyetsiz borsalar kimlik istemez ama oraya varlık getirmek için çoğu zaman yine KYC'li bir platformdan geçmek gerekir."},{"q":"KYC neden reddedilir?","a":"Bulanık fotoğraf, süresi dolmuş belge, bilgi uyumsuzluğu veya borsanın hizmet vermediği bir ülkeden başvuru en sık nedenlerdir. Ret mesajını okuyup belgeyi düzeltmek genellikle yeterlidir."}],"title":"KYC nedir? Kripto borsasında kimlik doğrulama","description":"KYC nedir, kripto borsaları neden kimlik ister, doğrulama seviyeleri limitleri nasıl etkiler ve verinizi nasıl korursunuz.","related":[["aml","AML (kara para aklamayı önleme)","AML (Anti-Money Laundering), suç gelirlerinin finansal sistemde temiz para gibi gösterilmesini önlemeye yönelik yasal kurallar, kontroller ve izleme süreçlerinin bütünüdür."],["travel-rule","Seyahat kuralı (travel rule)","Seyahat kuralı (travel rule), kripto hizmet sağlayıcılarının belirli transferlerde gönderen ve alıcı bilgilerini birbirine iletmesini zorunlu kılan, FATF'ın 16 numaralı tavsiyesine dayanan kuraldır."],["no-kyc-exchange","KYC'siz borsa (no-KYC exchange)","KYC'siz borsa, hesap açmak ve belirli limitlere kadar işlem yapmak için kimlik doğrulaması istemeyen merkezi veya merkeziyetsiz kripto alım satım platformudur."],["centralized-exchange","Merkezi borsa (CEX)","Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur."],["vasp","VASP (sanal varlık hizmet sağlayıcısı)","VASP (Virtual Asset Service Provider), başkaları adına kripto varlık alım satımı, takası, transferi veya saklaması yapan ve bu nedenle düzenlemeye tabi olan şirketlerdir."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC nasıl yapılır ve kimlik kime verilmelidir?"},"coin":null,"tool":null,"cta":false},"demo-trading":{"slug":"demo-trading","cat":"exchange-features","en":"Demo trading","contentLocale":"tr","term":"Demo işlem (deneme hesabı)","aka":["demo hesap","demo trading","sanal işlem","deneme hesabı"],"short":"Demo işlem, gerçek para kullanmadan, borsanın verdiği sanal bakiyeyle gerçek piyasa fiyatları üzerinde alım satım ve vadeli işlem pratiği yapmanızı sağlayan deneme modudur.","body":[["Birçok büyük borsa ",["vadeli işlemler","futures-contract"]," için demo modu sunar. Sanal ",["USDT","usdt"]," bakiyesiyle emir türlerini, kaldıracı, marjin modlarını, zarar durdur ve kâr al emirlerini deneyebilirsiniz. Yanlış butona basmanın, ters pozisyon açmanın veya likidasyonun nasıl göründüğünü para kaybetmeden öğrenirsiniz."],["Demo hesap gerçek piyasanın her şeyini yansıtmaz. Emirleriniz gerçek emir defterine girmediği için ",["kayma","slippage"]," ve dolum davranışı farklı olabilir. Asıl fark psikolojiktir: sanal parayla verilen kararlar, gerçek para söz konusu olduğunda farklılaşır."],"Demo hesabı arayüzü öğrenmek ve bir stratejinin kurallarını test etmek için kullanın. Gerçeğe geçerken küçük tutarlarla başlamak, demo ile gerçek arasındaki farkı yumuşatır."],"example":["Demo hesabınızda 10.000 sanal USDT ile ",["BTC","bitcoin"]," 60.000 iken 20 kat kaldıraçlı, 500 USDT teminatlı bir long açtığınızı düşünün. ",["Pozisyon büyüklüğü","position-sizing"]," 10.000 USDT, yani yaklaşık 0,1667 BTC'dir. Fiyat yüzde 5 düşüp 57.000'e inerse zarar 500 USDT olur; ücretler ve ",["bakım marjini","maintenance-margin"]," nedeniyle likidasyon bundan biraz önce, yaklaşık 57.300 civarında gerçekleşir. Bunu demoda yaşamak, gerçek hesapta 5 kat kaldıraçla ve zarar durdur emriyle başlamanın neden mantıklı olduğunu gösterir."],"mistakes":["Demo hesaptaki başarıyı gerçek hesapta aynı büyüklükte pozisyonlarla tekrarlamaya çalışmak.","Demoda zarar durdur kullanmayı alışkanlık hâline getirmemek.","Demo sonuçlarında kayma ve gerçek dolum farklarını hesaba katmamak."],"faq":[{"q":"Demo hesapta kazanılan para çekilebilir mi?","a":"Hayır. Demo bakiye sanaldır ve gerçek paraya çevrilemez. Bazı borsalar demo yarışmaları düzenleyebilir ama bunlar ayrı kampanyalardır."},{"q":"Demo işlem ne kadar süre yapılmalı?","a":"Belirli bir süre yoktur. Emir türlerini, kaldıracı ve likidasyonu rahatça anlayıp bir stratejiyi kurallara göre uygulayabildiğinizde küçük gerçek tutarlara geçebilirsiniz."}],"title":"Demo işlem nedir? Kripto demo hesap ile pratik","description":"Demo işlem nedir, kripto vadeli işlemleri sanal bakiyeyle nasıl denersiniz ve demo ile gerçek hesap arasındaki farklar nelerdir.","related":[["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."],["copy-trading","Kopya işlem (copy trading)","Kopya işlem (copy trading), seçtiğiniz bir trader'ın açtığı ve kapattığı pozisyonların, belirlediğiniz tutar ve oranla sizin hesabınızda otomatik olarak tekrarlanmasıdır."],["position-sizing","Pozisyon büyüklüğü (Position sizing)","Pozisyon büyüklüğü, bir işleme ne kadar sermaye ayıracağınızı zarar durdur seviyenize ve kabul edebileceğiniz en yüksek kayba göre belirleme yöntemidir."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10x kaldıraç: Daha fazla para mı, daha fazla risk mi?"},"coin":null,"tool":null,"cta":true}});
